WITH valid AS (SELECT *, DATE_FORMAT(delivered_date, 'yyyy-MM-dd') AS delivered_date_label FROM shipments WHERE delivered_date >= DATE '2023-06-02') SELECT carrier, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list, PERCENTILE_APPROX(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles, PERCENTILE_APPROX(cost, 0.95) AS cost_p95, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END), 0), 2) AS cost_per_delivered, STDDEV_SAMP(cost) AS cost_stddev FROM valid GROUP BY 1
